code_example:
// utils.h - WITHOUT inline (WRONG)
int add(int a, int b) {
    return a + b;  // Strong symbol T
}

// main.cpp
#include "utils.h"
int x = add(1, 2);

// other.cpp
#include "utils.h"  
int y = add(3, 4);

// Linker error:
// multiple definition of `add(int, int)'

// ─────────────────────────────────────

// utils.h - WITH inline (CORRECT)
inline int add(int a, int b) {
    return a + b;  // Weak symbol W
}

// main.cpp
#include "utils.h"
int x = add(1, 2);  // Weak symbol

// other.cpp
#include "utils.h"
int y = add(3, 4);  // Weak symbol

// Links successfully: linker keeps one copy
